-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.ete_llm_grade_patient_v1
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.ete_llm_grade_patient_v1 AS WITH ete_mentions AS (SELECT p.research_id, p.note_row_id, p.note_date, lower(main."trim"(json_extract_string(e."value", '$.entity_value'))) AS entity_value_norm, json_extract_string(e."value", '$.presence') AS presence, TRY_CAST(json_extract_string(e."value", '$.confidence') AS DOUBLE) AS confidence, json_extract_string(e."value", '$.evidence_text') AS evidence_text FROM main.note_entities_llm_pathology AS p , (SELECT unnest(CAST(json_extract(result_json, '$.entities') AS "json"[])) AS "value") AS e WHERE (json_extract_string(e."value", '$.entity_type') = 'extrathyroidal_extension')), classified AS (SELECT research_id, note_row_id, note_date, entity_value_norm, confidence, evidence_text, CASE  WHEN (((entity_value_norm ~~* '%gross%') OR (entity_value_norm = 'substernal extension') OR (entity_value_norm ~~* '%strap muscle%') OR (entity_value_norm ~~* '%trachea%') OR (entity_value_norm ~~* '%esophag%') OR (entity_value_norm ~~* '%recurrent laryngeal%'))) THEN ('gross') WHEN (((entity_value_norm ~~* '%microscop%') OR (entity_value_norm ~~* '%minimal%') OR (entity_value_norm ~~* '%perithyroid%fat%') OR (entity_value_norm ~~* '%focal%extension%'))) THEN ('microscopic') WHEN (((entity_value_norm = 'absent') OR (entity_value_norm ~~* 'no %') OR (entity_value_norm ~~* '%not identified%') OR (entity_value_norm = 'negative') OR (entity_value_norm ~~* '%no ete%'))) THEN ('absent') ELSE NULL END AS llm_grade FROM ete_mentions)SELECT research_id, CAST(max(CASE  WHEN ((llm_grade = 'gross')) THEN (1) ELSE 0 END) AS BOOLEAN) AS has_gross_llm, CAST(max(CASE  WHEN ((llm_grade = 'microscopic')) THEN (1) ELSE 0 END) AS BOOLEAN) AS has_micro_llm, CAST(max(CASE  WHEN ((llm_grade = 'absent')) THEN (1) ELSE 0 END) AS BOOLEAN) AS has_absent_llm, CASE  WHEN ((max(CASE  WHEN ((llm_grade = 'gross')) THEN (1) ELSE 0 END) = 1)) THEN ('gross') WHEN ((max(CASE  WHEN ((llm_grade = 'microscopic')) THEN (1) ELSE 0 END) = 1)) THEN ('microscopic') WHEN ((max(CASE  WHEN ((llm_grade = 'absent')) THEN (1) ELSE 0 END) = 1)) THEN ('absent') ELSE NULL END AS ete_grade_llm, count_star() AS n_ete_mentions FROM classified WHERE (llm_grade IS NOT NULL) GROUP BY research_id;
